<div class="d-flex justify-content-between mb-3"><h4>Stock Adjustment</h4><a class="btn btn-outline-secondary" href="<?= url('stock/adjustments') ?>">Back</a></div>
<form method="post" class="card card-body needs-validation" novalidate><?= csrf_field() ?><div class="row g-3">
<div class="col-md-6"><label class="form-label required-star">Warehouse</label><select name="warehouse_id" class="form-select" required><?php foreach ($warehouses as $w): ?><option value="<?= (int)$w['id'] ?>" <?= old('warehouse_id') == $w['id'] ? 'selected' : '' ?>><?= e($w['name']) ?></option><?php endforeach; ?></select></div>
<div class="col-md-6"><label class="form-label required-star">Product</label><select name="product_id" class="form-select" required><option value="">-- Select --</option><?php foreach ($products as $p): ?><option value="<?= (int)$p['id'] ?>" <?= old('product_id') == $p['id'] ? 'selected' : '' ?>><?= e($p['sku'] . ' - ' . $p['name']) ?></option><?php endforeach; ?></select></div>
<div class="col-md-4"><label class="form-label required-star">Adjustment type</label><select name="type" class="form-select" required><?php foreach (['increase' => 'Increase stock', 'decrease' => 'Decrease stock', 'damaged' => 'Record damaged', 'lost' => 'Record lost', 'reserve' => 'Reserve stock', 'release' => 'Release reserved', 'expired' => 'Write off - expired', 'spoilage' => 'Write off - spoiled / wastage', 'theft' => 'Write off - theft / shrinkage'] as $k => $l): ?><option value="<?= $k ?>" <?= old('type') === $k ? 'selected' : '' ?>><?= $l ?></option><?php endforeach; ?></select></div>
<div class="col-md-3"><label class="form-label required-star">Quantity</label><input type="number" name="qty" min="0.001" step="any" class="form-control" required value="<?= e(old('qty')) ?>"></div>
<div class="col-md-5"><label class="form-label required-star">Reason</label><input name="reason" minlength="3" maxlength="255" class="form-control" required value="<?= e(old('reason')) ?>"></div></div>
<div class="mt-3"><button class="btn btn-primary once"><i class="bi bi-check-lg"></i> Submit</button> <span class="text-muted small ms-2"><?= Auth::can('inventory.stock.approve') ? 'You can approve: the adjustment is applied immediately.' : 'Will be sent for approval.' ?></span></div></form>
